import { featureToggles } from 'config/featureToggle';
import { useLastDataRefresh } from 'contexts';
import { useBffData, useFeatureToggle } from 'hooks';
import { SharedKpis } from 'pages/enums';

import { InsightRecord } from '../../types';

export const usePowerBookInsights = () => {
  const { lastDataRefreshKpisDateMonthYear } = useLastDataRefresh();

  const [insightsEnabled, isInsightsLoading] = useFeatureToggle(
    featureToggles.pillar.portfolioBrand.submenus.brandPowerBookExport.insights,
  );

  const { data, loading: isLoadingInsightsData } = useBffData({
    id: SharedKpis.INSIGHTS,
    kpiGroup: 'power',
    skipRequest: !insightsEnabled,
    subFilters: {
      timeframe: null,
      zone: null,
      country: null,
      period: lastDataRefreshKpisDateMonthYear.power,
    },
  });

  return {
    insightsData: (data?.insights ?? []) as InsightRecord[],
    isLoadingInsightsData: isInsightsLoading || isLoadingInsightsData,
  };
};

export default usePowerBookInsights;
